-- Local-reviewed optimization; do not apply remotely without quota headroom.
-- Parent item inserts and removed-item owner lookups share this narrow index.
CREATE INDEX IF NOT EXISTS history_item_reference ON change_history(item_id,record_id,created_at) WHERE item_id IS NOT NULL;
DROP TRIGGER IF EXISTS public_index_insert;
DROP TRIGGER IF EXISTS public_index_update;
-- Public search index is updated atomically by projection writes, never by a separate job.
CREATE TABLE IF NOT EXISTS public_browse_index(record_id TEXT PRIMARY KEY REFERENCES public_records(record_id) ON DELETE CASCADE, revision INTEGER NOT NULL,deleted INTEGER NOT NULL,index_json TEXT NOT NULL CHECK(json_valid(index_json)));
CREATE TRIGGER IF NOT EXISTS public_index_insert AFTER INSERT ON public_records BEGIN INSERT INTO public_browse_index WITH summary AS MATERIALIZED (SELECT CASE WHEN json_extract(NEW.public_json,'$.list_type')='uncertain' THEN COALESCE(json_extract('{"p0023-l001":"have_list","p0060-l001":"complete","p0239-l017":"have_list","p0239-l018":"have_list","p0261-l003":"have_list","p0273-l029":"complete","p0273-l039":"want_list","p0375-l001":"have_list","p1809-l001":"have_list","p1996-l007":"have_list","p1996-l008":"complete","p1996-l009":"have_list","p1996-l010":"have_list","p1996-l011":"have_list","p1996-l012":"have_list","p1996-l013":"have_list","p1996-l014":"have_list","p1996-l015":"have_list","p1996-l016":"have_list","p1996-l017":"have_list","p1996-l018":"have_list","p1996-l019":"have_list","p1996-l020":"have_list","p2501-l001":"complete","p2529-l001":"have_list","p2851-l007":"complete","p2887-l001":"have_list","p3022-l006":"have_list"}','$.'||NEW.record_id),json_extract(NEW.public_json,'$.source_list_type'),'uncertain') ELSE json_extract(NEW.public_json,'$.list_type') END mode) SELECT NEW.record_id,NEW.revision,NEW.deleted,json_object('id',json_extract(NEW.public_json,'$.id'),'year',json_extract(NEW.public_json,'$.year'),'display_year',json_extract(NEW.public_json,'$.display_year'),'brand',json_extract(NEW.public_json,'$.brand'),'set_name',json_extract(NEW.public_json,'$.set_name'),'category',json_extract(NEW.public_json,'$.category'),'display_category',json_extract(NEW.public_json,'$.display_category'),'section',json_extract(NEW.public_json,'$.section'),'notes',json(json_extract(NEW.public_json,'$.notes')),'prefixes',json(json_extract(NEW.public_json,'$.prefixes')),'entry_order',json_extract(NEW.public_json,'$.entry_order'),'source_list_type',json_extract(NEW.public_json,'$.source_list_type'),'list_type',s.mode,'revision',NEW.revision,'index_only',json('true'),'card_numbers',json('[]'),'items',json_array(COALESCE((SELECT group_concat(value,' ') FROM (
 SELECT json_extract(e.value,'$.value') value FROM json_each(NEW.public_json,'$.groups') g JOIN json_each(g.value,'$.entries') e
 WHERE s.mode IN ('want_list','have_list') AND (json_extract(g.value,'$.list_type')=s.mode OR json_extract(g.value,'$.kind')='primary' AND json_extract(g.value,'$.list_type')='uncertain')
 AND (json_extract(e.value,'$.state') IS NULL OR json_extract(e.value,'$.state') IN (CASE WHEN s.mode='have_list' THEN 'owned' ELSE 'wanted' END,CASE WHEN s.mode='want_list' THEN 'pending' ELSE 'owned' END))
 AND NOT(NEW.record_id='p0526-l006' AND json_extract(g.value,'$.kind')='primary' AND json_extract(e.value,'$.field_key')='items')
 UNION ALL SELECT json_extract(g.value,'$.label') FROM json_each(NEW.public_json,'$.groups') g WHERE json_extract(g.value,'$.list_type')=s.mode
)),''))) FROM summary s WHERE 1 ON CONFLICT(record_id) DO UPDATE SET revision=excluded.revision,deleted=excluded.deleted,index_json=excluded.index_json; END;
CREATE TRIGGER IF NOT EXISTS public_index_update AFTER UPDATE ON public_records BEGIN INSERT INTO public_browse_index WITH summary AS MATERIALIZED (SELECT CASE WHEN json_extract(NEW.public_json,'$.list_type')='uncertain' THEN COALESCE(json_extract('{"p0023-l001":"have_list","p0060-l001":"complete","p0239-l017":"have_list","p0239-l018":"have_list","p0261-l003":"have_list","p0273-l029":"complete","p0273-l039":"want_list","p0375-l001":"have_list","p1809-l001":"have_list","p1996-l007":"have_list","p1996-l008":"complete","p1996-l009":"have_list","p1996-l010":"have_list","p1996-l011":"have_list","p1996-l012":"have_list","p1996-l013":"have_list","p1996-l014":"have_list","p1996-l015":"have_list","p1996-l016":"have_list","p1996-l017":"have_list","p1996-l018":"have_list","p1996-l019":"have_list","p1996-l020":"have_list","p2501-l001":"complete","p2529-l001":"have_list","p2851-l007":"complete","p2887-l001":"have_list","p3022-l006":"have_list"}','$.'||NEW.record_id),json_extract(NEW.public_json,'$.source_list_type'),'uncertain') ELSE json_extract(NEW.public_json,'$.list_type') END mode,CASE WHEN json_extract(OLD.public_json,'$.list_type')='uncertain' THEN COALESCE(json_extract('{"p0023-l001":"have_list","p0060-l001":"complete","p0239-l017":"have_list","p0239-l018":"have_list","p0261-l003":"have_list","p0273-l029":"complete","p0273-l039":"want_list","p0375-l001":"have_list","p1809-l001":"have_list","p1996-l007":"have_list","p1996-l008":"complete","p1996-l009":"have_list","p1996-l010":"have_list","p1996-l011":"have_list","p1996-l012":"have_list","p1996-l013":"have_list","p1996-l014":"have_list","p1996-l015":"have_list","p1996-l016":"have_list","p1996-l017":"have_list","p1996-l018":"have_list","p1996-l019":"have_list","p1996-l020":"have_list","p2501-l001":"complete","p2529-l001":"have_list","p2851-l007":"complete","p2887-l001":"have_list","p3022-l006":"have_list"}','$.'||OLD.record_id),json_extract(OLD.public_json,'$.source_list_type'),'uncertain') ELSE json_extract(OLD.public_json,'$.list_type') END old_mode) SELECT NEW.record_id,NEW.revision,NEW.deleted,json_object('id',json_extract(NEW.public_json,'$.id'),'year',json_extract(NEW.public_json,'$.year'),'display_year',json_extract(NEW.public_json,'$.display_year'),'brand',json_extract(NEW.public_json,'$.brand'),'set_name',json_extract(NEW.public_json,'$.set_name'),'category',json_extract(NEW.public_json,'$.category'),'display_category',json_extract(NEW.public_json,'$.display_category'),'section',json_extract(NEW.public_json,'$.section'),'notes',json(json_extract(NEW.public_json,'$.notes')),'prefixes',json(json_extract(NEW.public_json,'$.prefixes')),'entry_order',json_extract(NEW.public_json,'$.entry_order'),'source_list_type',json_extract(NEW.public_json,'$.source_list_type'),'list_type',s.mode,'revision',NEW.revision,'index_only',json('true'),'card_numbers',json('[]'),'items',CASE WHEN s.mode=s.old_mode AND json_extract(NEW.public_json,'$.groups') IS json_extract(OLD.public_json,'$.groups') AND EXISTS(SELECT 1 FROM public_browse_index WHERE record_id=NEW.record_id AND json_type(index_json,'$.items')='array') THEN json((SELECT json_extract(index_json,'$.items') FROM public_browse_index WHERE record_id=NEW.record_id)) ELSE json_array(COALESCE((SELECT group_concat(value,' ') FROM (
 SELECT json_extract(e.value,'$.value') value FROM json_each(NEW.public_json,'$.groups') g JOIN json_each(g.value,'$.entries') e
 WHERE s.mode IN ('want_list','have_list') AND (json_extract(g.value,'$.list_type')=s.mode OR json_extract(g.value,'$.kind')='primary' AND json_extract(g.value,'$.list_type')='uncertain')
 AND (json_extract(e.value,'$.state') IS NULL OR json_extract(e.value,'$.state') IN (CASE WHEN s.mode='have_list' THEN 'owned' ELSE 'wanted' END,CASE WHEN s.mode='want_list' THEN 'pending' ELSE 'owned' END))
 AND NOT(NEW.record_id='p0526-l006' AND json_extract(g.value,'$.kind')='primary' AND json_extract(e.value,'$.field_key')='items')
 UNION ALL SELECT json_extract(g.value,'$.label') FROM json_each(NEW.public_json,'$.groups') g WHERE json_extract(g.value,'$.list_type')=s.mode
)),'')) END) FROM summary s WHERE 1 ON CONFLICT(record_id) DO UPDATE SET revision=excluded.revision,deleted=excluded.deleted,index_json=excluded.index_json; END;
